package website

import (
	"fmt"
	"html/template"
	"io/fs"
	"log"
	"math/rand"
	"net/http"
	"regexp"
	"strconv"
	"strings"

	"donseba/go-webthings-docs/internal/moduledoc"

	router "github.com/donseba/go-router"
)

// modulesSite serves modules.<domain>: one site per bundled go-webthings
// module, generated by tools/moduledocs into the docs section's modules/.
type modulesSite struct {
	docs    *docsRenderer
	modules []moduledoc.Module
	bySlug  map[string]*moduledoc.Module
	icons   map[string]bool
}

// ModuleGroup is a group of modules on the website.
type ModuleGroup struct {
	Name    string
	Intro   string
	Modules []ModuleCard
}

// ModuleCard is a module in a list of modules.
type ModuleCard struct {
	Slug       string
	Name       string
	Summary    string
	Icon       string
	URL        string
	SourceURL  string
	Facts      []string
	Deprecated bool
}

// ModulesIndexData is the dot of the modules home page.
type ModulesIndexData struct {
	Article DocsArticleData
	Groups  []ModuleGroup
}

// ModulePageData is the dot of a module's pages.
type ModulePageData struct {
	Article DocsArticleData
	Module  *moduledoc.Module
	// Guide is the module's README with links to the docs resolved.
	Guide template.HTML
	// DocsURL is the docs subdomain for this request's host.
	DocsURL string
	Icon    string
	Facts   []string
	// Previous and Next are the neighbouring pages of the module.
	Previous *ModulePageLink
	Next     *ModulePageLink
}

// ModulePageLink links to one page of a module.
type ModulePageLink struct {
	Label string
	URL   string
}

const (
	modulesDataDir  = "modules"
	modulesTemplate = "templates/modules/shared.gohtml"
)

var groupIntros = map[string]string{
	"Content":  "Things editors write and publish, with every language of the site.",
	"Visitors": "Things visitors send: messages, votes, sign-ups and contributions.",
	"Site":     "Site-wide behaviour that is not placed on a page.",
}

func newModulesSite() *modulesSite {
	list, err := moduledoc.Load(websiteFS, modulesDataDir)
	if err != nil {
		log.Printf("modules: %v", err)
	}

	site := &modulesSite{
		modules: list,
		bySlug:  map[string]*moduledoc.Module{},
		icons:   spriteIcons(websiteFS, "assets/img/icons.svg"),
	}

	for i := range site.modules {
		site.bySlug[site.modules[i].Slug] = &site.modules[i]
	}

	site.docs = newDocsRenderer(docsRendererConfig{
		Chrome: &chrome{
			section:   "modules",
			title:     "go-webthings modules",
			subtitle:  "bundled modules for go-webthings sites",
			logoImage: "/assets/img/logo-go-webthings.png",
			gitHubURL: "https://github.com/donseba/go-webthings/tree/main/modules",
			rail:      site.rail,
		},
		Origin:    "https://modules.gowebthings.com",
		BasePath:  "/",
		AppName:   "modules",
		LogoImage: "/assets/img/logo-go-webthings.png",
		Title:     "go-webthings modules",
		Subtitle:  "bundled modules for go-webthings sites",
		GitHubURL: "https://github.com/donseba/go-webthings/tree/main/modules",
	})

	return site
}

// rail lists every module by group; the module in the address is active.
func (s *modulesSite) rail(r *http.Request, _ string) DocsRailPage {
	current, _, _ := strings.Cut(strings.Trim(requestPath(r), "/"), "/")

	page := DocsRailPage{
		Groups: []DocsRailGroup{{
			Items: []DocsRailItem{
				{Label: "All modules", URL: "/", Icon: "box", Active: current == ""},
			},
		}},
	}

	for _, name := range moduledoc.Groups {
		group := DocsRailGroup{Name: name}

		for i := range s.modules {
			module := &s.modules[i]
			if module.Group != name {
				continue
			}

			group.Items = append(group.Items, DocsRailItem{
				Label:  module.Name,
				URL:    "/" + module.Slug,
				Icon:   s.icon(module),
				Active: module.Slug == current,
			})
		}

		if len(group.Items) > 0 {
			page.Groups = append(page.Groups, group)
		}
	}

	return page
}

// registerModulesRoutes serves every page from "/": a /{module}/{page}
// pattern would conflict with the /assets/ file server.
func registerModulesRoutes(r *router.Router, domain string) {
	r.Get("/", moduleSite.route).As(fmt.Sprintf("%s.modules.index", domain))
}

// route serves /, /{module} and /{module}/{page}.
func (s *modulesSite) route(w http.ResponseWriter, r *http.Request) {
	path := strings.Trim(r.URL.Path, "/")
	if path == "" {
		s.index(w, r)

		return
	}

	slug, page, _ := strings.Cut(path, "/")
	if strings.Contains(page, "/") || strings.HasSuffix(r.URL.Path, "/") {
		s.notFound(w, r)

		return
	}

	s.page(w, r, slug, page)
}

func (s *modulesSite) index(w http.ResponseWriter, r *http.Request) {
	page := docsPage{
		Template:    "templates/modules/index.gohtml",
		Title:       "Modules for go-webthings sites",
		Description: "What each bundled module adds to a site and how to use it, with its templates, template functions, settings and database tables.",
		Section:     "modules",
	}

	data := ModulesIndexData{
		Article: article(page),
		Groups:  s.groups(func(slug string) string { return "/" + slug }),
	}

	s.docs.write(w, r, http.StatusOK, page, data, s.sidebar(r.URL.Path, nil))
}

func (s *modulesSite) page(w http.ResponseWriter, r *http.Request, slug, current string) {
	module, ok := s.bySlug[slug]
	if !ok {
		s.notFound(w, r)

		return
	}

	index := -1

	for i, p := range moduledoc.Pages {
		if p.Path == current {
			index = i
		}
	}

	if index < 0 {
		s.notFound(w, r)

		return
	}

	label := moduledoc.Pages[index].Label
	page := docsPage{
		Template:    "templates/modules/" + templateName(current) + ".gohtml",
		Shared:      []string{modulesTemplate},
		Title:       module.Name,
		Description: module.Summary,
		Section:     module.Group + " module",
	}

	if current != "" {
		page.Title = module.Name + " " + strings.ToLower(label)
		page.Description = pageDescription(module, current)
		page.Section = module.Name + " module"
	}

	data := ModulePageData{
		Article: article(page),
		Module:  module,
		Guide:   resolveLinks(r, module.Guide),
		DocsURL: docsHomeURL(r),
		Icon:    s.icon(module),
		Facts:   facts(module),
	}

	if index > 0 {
		previous := moduledoc.Pages[index-1]
		data.Previous = &ModulePageLink{Label: previous.Label, URL: modulePath(module.Slug, previous.Path)}
	}

	if index < len(moduledoc.Pages)-1 {
		next := moduledoc.Pages[index+1]
		data.Next = &ModulePageLink{Label: next.Label, URL: modulePath(module.Slug, next.Path)}
	}

	s.docs.write(w, r, http.StatusOK, page, data, s.sidebar(r.URL.Path, module))
}

func (s *modulesSite) notFound(w http.ResponseWriter, r *http.Request) {
	page := docsPage{
		Template:    "templates/modules/index.gohtml",
		Title:       "Module not found",
		Description: "There is no module at this address. These are the modules go-webthings bundles.",
		Section:     "not found",
	}

	data := ModulesIndexData{
		Article: article(page),
		Groups:  s.groups(func(slug string) string { return "/" + slug }),
	}

	s.docs.write(w, r, http.StatusNotFound, page, data, s.sidebar(r.URL.Path, nil))
}

// sidebar lists the pages of the current module; without one it is empty
// and hidden.
func (s *modulesSite) sidebar(current string, module *moduledoc.Module) DocsNavPage {
	if module == nil {
		return DocsNavPage{}
	}

	items := make([]NavItem, 0, len(moduledoc.Pages))

	for _, p := range moduledoc.Pages {
		items = append(items, NavItem{Path: modulePath(module.Slug, p.Path), Label: p.Label, Group: "Pages"})
	}

	nav := docsNavPage(items, "", current)
	nav.Head = &DocsNavHead{
		Title:     module.Name,
		Subtitle:  module.Group + " module",
		URL:       "/" + module.Slug,
		Icon:      s.icon(module),
		SourceURL: module.SourceURL,
	}

	return nav
}

// groups lists the modules by group, linked with linkFor.
func (s *modulesSite) groups(linkFor func(slug string) string) []ModuleGroup {
	var groups []ModuleGroup

	for _, name := range moduledoc.Groups {
		group := ModuleGroup{Name: name, Intro: groupIntros[name]}

		for i := range s.modules {
			module := &s.modules[i]
			if module.Group != name {
				continue
			}

			group.Modules = append(group.Modules, ModuleCard{
				Slug:       module.Slug,
				Name:       module.Name,
				Summary:    module.Summary,
				Icon:       s.icon(module),
				URL:        linkFor(module.Slug),
				SourceURL:  module.SourceURL,
				Facts:      facts(module),
				Deprecated: module.Deprecated != "",
			})
		}

		if len(group.Modules) > 0 {
			groups = append(groups, group)
		}
	}

	return groups
}

// icon is the module's admin icon when the sprite has it.
func (s *modulesSite) icon(module *moduledoc.Module) string {
	for _, section := range module.Admin {
		if s.icons[section.Icon] {
			return section.Icon
		}
	}

	return "box"
}

// facts are short notes about what a module adds.
func facts(module *moduledoc.Module) []string {
	var list []string

	if module.Parts.Public {
		list = append(list, "page")
	}

	if module.Parts.Actions {
		list = append(list, "visitor forms")
	}

	if module.Parts.Feeds {
		list = append(list, "feeds")
	}

	if module.Parts.Links {
		list = append(list, "link check")
	}

	if module.Parts.API {
		list = append(list, "content API")
	}

	if module.Parts.Middleware {
		list = append(list, "middleware")
	}

	if len(module.Templates) > 0 {
		list = append(list, count(len(module.Templates), "template", "templates"))
	}

	if len(module.Components) > 0 {
		list = append(list, count(len(module.Components), "component", "components"))
	}

	if len(module.Funcs) > 0 {
		list = append(list, count(len(module.Funcs), "function", "functions"))
	}

	if len(module.Mail) > 0 {
		list = append(list, count(len(module.Mail), "e-mail", "e-mails"))
	}

	list = append(list, count(len(module.Tables), "table", "tables"))

	return list
}

func count(n int, singular, plural string) string {
	if n == 1 {
		return "1 " + singular
	}

	return strconv.Itoa(n) + " " + plural
}

func article(page docsPage) DocsArticleData {
	return DocsArticleData{
		Title:       page.Title,
		Description: page.Description,
		Section:     page.Section,
		PromptFace:  docsPromptFaces[rand.Intn(len(docsPromptFaces))],
	}
}

func modulePath(slug, page string) string {
	if page == "" {
		return "/" + slug
	}

	return "/" + slug + "/" + page
}

func templateName(page string) string {
	if page == "" {
		return "overview"
	}

	return page
}

func pageDescription(module *moduledoc.Module, page string) string {
	switch page {
	case "configuration":
		return "Adding " + module.Name + " to an app: the constructor, its options, the admin sections, settings and the addresses it serves."
	case "templates":
		return "The template functions " + module.Name + " adds, the templates and components it renders and the data they receive."
	case "database":
		return "The migrations and tables of " + module.Name + ", for SQLite, PostgreSQL and MySQL."
	case "api":
		return "The Go API of " + module.Name + ", for the website's own code."
	default:
		return module.Summary
	}
}

var symbolID = regexp.MustCompile(`<symbol id="([^"]+)"`)

// spriteIcons are the symbol ids of an SVG sprite.
func spriteIcons(fsys fs.FS, path string) map[string]bool {
	icons := map[string]bool{}

	body, err := fs.ReadFile(fsys, path)
	if err != nil {
		return icons
	}

	for _, match := range symbolID.FindAllStringSubmatch(string(body), -1) {
		icons[match[1]] = true
	}

	return icons
}
